<script setup>
import { router, Head, Link } from '@inertiajs/vue3';
import { reactive } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';

const props = defineProps({ lots: Object, filters: Object, products: Array, suppliers: Array, totalsByUnit: Array, counts: Object });
const search = reactive({ q: props.filters.q ?? '', product_id: props.filters.product_id ?? '', supplier_id: props.filters.supplier_id ?? '', received_month: props.filters.received_month ?? '', availability: props.filters.availability ?? '' });
const number = (value, scale = 4) => new Intl.NumberFormat('ja-JP', { maximumFractionDigits: scale }).format(Number(value) || 0);
function submit() { router.get('/admin/inventory-lots', search, { preserveState: true, replace: true }); }
function reset() { Object.assign(search, { q: '', product_id: '', supplier_id: '', received_month: '', availability: '' }); router.get('/admin/inventory-lots'); }
</script>

<template>
  <AdminLayout>
    <Head title="ロット在庫" />
    <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-bold tracking-widest text-emerald-700">在庫</p><h1 class="mt-3 text-3xl font-bold">ロット在庫</h1><p class="mt-3 text-sm text-slate-500">ロットごとの残数と、販売商品全体の在庫量を確認します。</p></div><Link href="/admin/purchase-receipts/create" class="btn-primary">＋ 入庫を登録</Link></div>
    <div class="my-7 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div class="rounded-xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">ロット総数</p><p class="mt-2 text-2xl font-semibold">{{ counts.all }}<span class="ml-2 text-xs font-normal text-slate-400">件</span></p></div><div class="rounded-xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">在庫あり</p><p class="mt-2 text-2xl font-semibold">{{ counts.available }}<span class="ml-2 text-xs font-normal text-slate-400">件</span></p></div><div v-for="total in totalsByUnit" :key="total.id" class="rounded-xl border border-emerald-100 bg-emerald-50 p-5"><p class="text-xs text-emerald-800">検索結果の総在庫（{{ total.name }}）</p><p class="mt-2 text-2xl font-semibold text-emerald-950">{{ number(total.total_quantity, total.quantity_scale) }}<span class="ml-2 text-xs font-normal">{{ total.name }}</span></p></div></div>
    <form @submit.prevent="submit" class="mb-6 grid gap-4 rounded-xl border border-slate-200 bg-white p-5 sm:grid-cols-2 lg:grid-cols-6"><div><label for="lot-q" class="mb-2 block text-sm font-medium">商品・ロット番号</label><input id="lot-q" v-model="search.q" class="field" maxlength="150" /></div><div><label for="lot-product" class="mb-2 block text-sm font-medium">販売商品</label><select id="lot-product" v-model="search.product_id" class="field"><option value="">すべて</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.sku }}｜{{ product.name }}</option></select></div><div><label for="lot-supplier" class="mb-2 block text-sm font-medium">仕入先</label><select id="lot-supplier" v-model="search.supplier_id" class="field"><option value="">すべて</option><option v-for="supplier in suppliers" :key="supplier.id" :value="supplier.id">{{ supplier.name }}</option></select></div><div><label for="lot-month" class="mb-2 block text-sm font-medium">入庫月</label><input id="lot-month" v-model="search.received_month" type="month" class="field" /></div><div><label for="lot-availability" class="mb-2 block text-sm font-medium">在庫状態</label><select id="lot-availability" v-model="search.availability" class="field"><option value="">すべて</option><option value="available">在庫あり</option><option value="depleted">在庫なし</option></select></div><div class="flex items-end gap-3"><button type="submit" class="btn-primary">検索</button><button type="button" @click="reset" class="nav-link px-2 py-3">解除</button></div></form>
    <section class="overflow-hidden rounded-xl border border-slate-200 bg-white"><div class="border-b border-slate-200 px-5 py-4 text-sm font-semibold">検索結果 <span class="ml-2 text-slate-500">{{ lots.total }} 件</span></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="px-5 py-4">販売商品・ロット</th><th class="px-5 py-4">仕入先</th><th class="px-5 py-4">入庫日</th><th class="px-5 py-4">期限日</th><th class="px-5 py-4 text-right">入庫数</th><th class="px-5 py-4 text-right">現在庫</th><th class="px-5 py-4 text-right">仕入単価</th><th class="px-5 py-4">入庫番号</th></tr></thead><tbody>
      <tr v-for="lot in lots.data" :key="lot.id" class="border-t border-slate-100 hover:bg-slate-50"><td class="px-5 py-4"><p class="font-semibold text-emerald-900">{{ lot.product.name }}</p><p class="mt-1 text-xs text-slate-500">{{ lot.product.sku }} ／ {{ lot.lot_number }}</p></td><td class="px-5 py-4">{{ lot.supplier.name }}</td><td class="px-5 py-4 whitespace-nowrap">{{ lot.received_on }}</td><td class="px-5 py-4 whitespace-nowrap">{{ lot.expires_on || '—' }}</td><td class="px-5 py-4 text-right tabular-nums">{{ number(lot.initial_quantity, lot.product.unit.quantity_scale) }} {{ lot.product.unit.name }}</td><td class="px-5 py-4 text-right font-semibold tabular-nums" :class="Number(lot.current_quantity) > 0 ? 'text-emerald-800' : 'text-slate-400'">{{ number(lot.current_quantity, lot.product.unit.quantity_scale) }} {{ lot.product.unit.name }}</td><td class="px-5 py-4 text-right tabular-nums">{{ number(lot.unit_purchase_price) }}</td><td class="px-5 py-4"><Link :href="`/admin/purchase-receipts/${lot.receipt_line.receipt.id}/edit`" class="nav-link">{{ lot.receipt_line.receipt.receipt_number }}</Link></td></tr>
      <tr v-if="!lots.data.length"><td colspan="8" class="px-6 py-14 text-center"><p class="font-semibold">{{ counts.all ? '条件に一致するロット在庫がありません。' : 'ロット在庫はまだありません。' }}</p><p class="mt-2 text-sm text-slate-500">確定した入庫がロット在庫として表示されます。</p></td></tr>
    </tbody></table></div><nav aria-label="ロット在庫一覧のページ切り替え" class="flex items-center justify-between border-t border-slate-200 px-5 py-4 text-sm"><span>{{ lots.current_page }} / {{ lots.last_page }} ページ</span><div class="flex gap-5"><Link v-if="lots.prev_page_url" :href="lots.prev_page_url" class="nav-link">← 前へ</Link><Link v-if="lots.next_page_url" :href="lots.next_page_url" class="nav-link">次へ →</Link></div></nav></section>
  </AdminLayout>
</template>
